/** Persistent danger, real treatment and permanent NPC deaths. SR-XF-022/023. */
import {pay,log,RESOURCES} from './ea-data.mjs';
import {recordFactSR,publishFactSR,recordClaimSR,makeWorldPerson,activateRootSR,discoverSceneSR,setRouteConditionSR,worldResourcePaySR} from './ea-sr-world.mjs';
import {initAftermath,activateRainAftermath,prepareDeathAftermath,discloseAftermathObligations,reconcileAftermathKnowledge,markAftermathKnowledge,viewAftermath,aftermathAction} from './ea-sr-aftermath.mjs';
let deathCleanup=()=>{};
export function configureSRCrises({onPermanentDeath}={}){if(onPermanentDeath)deathCleanup=onPermanentDeath;}
const MASTER='person:master', HERBALIST='person:su-yelan',SCENE='scene:valley';
export function initSRCrises(s,addDisciple){s.crisesById??={};s.deathRecordsByPersonId??={};if(s.srCrises)return;s.srCrises={version:1,lastTick:s.worldTick,nextId:1,rainChain:null,traps:{},activeTreatment:null,cooldownUntil:s.worldTick};makeWorldPerson(s,HERBALIST,'苏叶岚','scene:market',7,addDisciple);makeWorldPerson(s,'person:yao-zhong','姚仲','scene:market',7,addDisciple);makeWorldPerson(s,'person:qing-luo','青萝',SCENE,8,addDisciple);s.personsById[HERBALIST].location={kind:'local',sceneId:'scene:market',x:25,y:29};s.personsById['person:yao-zhong'].location={kind:'local',sceneId:'scene:market',x:30,y:35};s.personsById['person:qing-luo'].location={kind:'local',sceneId:SCENE,x:43,y:24};s.personsById[HERBALIST].mind.reason='独立药师为溪口伤者采药，是否出行由自己决定';s.personsById['person:yao-zhong'].mind.reason='药商想控制雨后紧缺供给，真实药材存在但旧约未披露';s.personsById['person:qing-luo'].mind.reason='守护药地旧约，愿意交换但反对毁封夺药';s.stockpilesById['stockpile:su-yelan']??={id:'stockpile:su-yelan',ownerId:HERBALIST,custodianId:HERBALIST,capacity:100,access:'private',position:{sceneId:'scene:market',x:25,y:29},resources:{...Object.fromEntries(Object.keys(RESOURCES).map(k=>[k,0])),herb:4,food:3}};s.personsById[HERBALIST].rescueEquipment??={rope:0};}
export function startCrisisSR(s,{id,personId,sceneId=SCENE,x=47,y=34.5,cause='trapped-water',durationTicks=900,selfRescue=false,messageDelayTicks=60,injuryScale=1,deathThreshold='deadline'}){if(id&&s.crisesById[id])return s.crisesById[id];const p=s.personsById[personId];if(!p||p.lifeStatus==='dead')throw Error('目标不再存活');if(!Number.isSafeInteger(durationTicks)||durationTicks<1||!Number.isSafeInteger(messageDelayTicks)||messageDelayTicks<0||!Number.isFinite(x)||!Number.isFinite(y))throw Error('危机需要有效空间与正整数时间预算');if(Object.values(s.crisesById).some(c=>c.personId===personId&&c.status==='active'))throw Error('此人已有持续危机，不重复占用身体');if(personId===MASTER&&cause!=='borrow-energy')throw Error('掌门危机由恢复边界处理，不创建永久死亡');const key=id||`crisis:sr:${s.srCrises.nextId++}`;const c={id:key,personId,sceneId,x,y,cause,stage:'forming',startedTick:s.worldTick,lastTick:s.worldTick,progressTicks:0,durationTicks,stageStartedTick:s.worldTick,stageProgressTicks:0,stageDurationTicks:100,status:'active',selfRescue,escapeStartedTick:null,messageDueTick:s.worldTick+messageDelayTicks,messageDelivered:false,known:false,treatment:null,outcome:null,injuryApplied:0,deathFactId:null,injuryScale,deathThreshold};p.location={kind:'local',sceneId,x,y};p.bodyState='impaired';if(p.mind)p.mind.activity='sr-crisis';else p.action='rest';s.crisesById[key]=c;return c;}
export function activateRainChainSR(s){const r=s.srCrises;if(r.rainChain)return r.rainChain;if(s.worldTick<r.cooldownUntil)throw Error('上次危机后尚在恢复期');const weather=s.weatherByRegionId?.['region:yunxiu']?.phase||s.world.weather.id;if(weather!=='rain')throw Error('持续降雨时药材供给变化才会触发此链');const p=s.personsById[HERBALIST];if(p.lifeStatus==='dead')throw Error('苏叶岚已身死，不会刷新一个替身');activateRainAftermath(s);activateRootSR(s,{id:'root:rain-herbalist:v1',scheme:true,authorCardId:'card:rain-herbalist:v1'});const id='travel:npc:su-yelan';s.travelsById[id]={id,from:'scene:market',destination:SCENE,routeIds:['route:valley-market'],durationTicks:100,progressTicks:0,lastTick:s.worldTick,startedTick:s.worldTick,status:'traveling',participantIds:[HERBALIST],purpose:'为溪口山民取得真实救急草药'};const supplies=s.stockpilesById['stockpile:su-yelan'];if(supplies.resources.food<1)throw Error('苏叶岚缺少实际行粮，不会无物资出行');supplies.resources.food--;supplies.position={kind:'travel',travelId:id};p.location={kind:'travel',travelId:id};p.mind.away={kind:'sr',id};p.mind.activity='travel';r.rainChain={id:'root:rain-herbalist:v1',stage:'departing',activatedTick:s.worldTick,travelId:id,crisisId:null,status:'active',guardianAgreement:false};setRouteConditionSR(s,'route:bridge','blocked');recordFactSR(s,'fact:rain:road',{kind:'road-damage',sceneId:SCENE,text:'持续降雨使石桥受损，山腰绕行仍可通达'});recordClaimSR(s,{id:'claim:rain:merchant',topic:'herbalist',speakerId:'person:yao-zhong',sourceId:'source:yao-personal',text:'侧洞确有药材，采出便可救急。',truthType:'omission'});recordClaimSR(s,{id:'claim:rain:departure',topic:'herbalist',speakerId:HERBALIST,sourceId:'source:su-departure',text:'苏叶岚自愿去云岫山谷采药，约好到洞口后回报。',truthType:'truth'});s.srWorld.knownLocations[HERBALIST]={sceneId:SCENE,observedTick:s.worldTick,sourceId:'source:su-departure'};discoverSceneSR(s,SCENE);log(s,'苏叶岚为救治溪口伤者自愿出发；石桥断裂，可选择查验与绕行。');return r.rainChain;}
function social(s,c,kind){initAftermath(s);const key=`fact:social:${c.id}:${kind}`;if(s.factsById[key])return;recordFactSR(s,key,{kind,actorId:MASTER,personId:c.personId,sceneId:c.sceneId,text:kind==='rescue'?`掌门实际救下${s.personsById[c.personId].name}`:`${s.personsById[c.personId].name}的危机结果已留存`});publishFactSR(s,key);if(kind==='rescue')publishFactSR(s,key,c.personId);markAftermathKnowledge(s,key);reconcileAftermathKnowledge(s);}
export function recordPermanentDeathSR(s,personId,{cause,sceneId,factId}={}){initAftermath(s);if(s.deathRecordsByPersonId[personId])return s.factsById[s.deathRecordsByPersonId[personId].factId]||s.deathRecordsByPersonId[personId];const p=s.personsById[personId];if(!p||personId===MASTER)throw Error('永久死亡仅用于已有NPC');deathCleanup(s,personId);if(p.location?.kind==='local')for(const st of Object.values(s.stockpilesById))if(st.ownerId===personId&&st.id.startsWith('stockpile:content:')){st.position={sceneId:p.location.sceneId,x:p.location.x,y:p.location.y};st.source='身死时留下的本人有限契约物资；原产权保留';}const id=factId||`fact:death:${personId}`;const f=recordFactSR(s,id,{kind:'death',personId,cause:cause||'危机不可逆损伤',sceneId:sceneId||p.location?.sceneId,position:p.location?.kind==='local'?{x:p.location.x,y:p.location.y}:null,text:`${p.name}已身死，姓名、关系与遗物仍留在世界`});s.deathRecordsByPersonId[personId]={personId,factId:id,atTick:s.worldTick,sceneId:f.sceneId};prepareDeathAftermath(s,personId);p.lifeStatus='dead';p.bodyState='dead';p.deathFactId=id;p.job=null;p.mind.activity='dead';p.mind.away=null;p.mind.mentor=null;p.mind.learning=null;p.role=null;p.activityId=null;s.homeMemberIds=s.homeMemberIds.filter(id=>id!==personId);if(s.society?.officers)for(const [role,id]of Object.entries(s.society.officers))if(id===p.id)s.society.officers[role]=null;if(s.society?.departed&&!s.society.departed.some(x=>x.id===p.id))s.society.departed.push({id:p.id,name:p.name,realm:p.realm,reason:'永久身死',time:s.time,lifeStatus:'dead',memories:[]});for(const other of s.disciples)if(other.mind.mentorId===p.id)other.mind.mentorId=null;p.mind.mentorId=null;p.mind.office=null;if(s.society?.offices)for(const[k,v]of Object.entries(s.society.offices))if(v===p.id||v?.personId===personId||v?.holderId===p.id)s.society.offices[k]=null;for(const peak of Object.values(s.society?.peaks||{})){if(peak.hostId===p.id){peak.active=false;peak.reason='主持者永久身死，历史归属保留待继任';}if(peak.mentorId===p.id)peak.mentorId=null;}for(const a of Object.values(s.activitiesById))if(a.personId===personId&&!['completed','cancelled'].includes(a.phase)){a.phase='cancelled';a.reason='人物永久身死';}for(const[id,res]of Object.entries(s.reservationsById))if(res.personId===personId)delete s.reservationsById[id];s.itemsById??={};const relicId=`item:relic:${personId}`;s.itemsById[relicId]??={id:relicId,definitionId:'personal-relic',ownerId:personId,holderId:null,location:{kind:'scene',id:f.sceneId,x:f.position?.x??47,y:f.position?.y??31},condition:1,sourceFactId:id,name:`${p.name}的遗物`};return f;}
function end(s,c,outcome){if(c.personId===MASTER&&outcome==='dead')outcome='damaged';c.status='resolved';c.stage='resolved';c.outcome=outcome;c.resolvedTick=s.worldTick;const p=s.personsById[c.personId];if(outcome==='dead'){c.deathFactId=recordPermanentDeathSR(s,c.personId,{cause:c.cause,sceneId:c.sceneId}).id;recordFactSR(s,`fact:crisis:${c.id}:alternative`,{kind:'alternative-evidence',sceneId:'scene:quarry',text:'石桥旧雇佣单与工具记录仍保存，药师身死不会堵住复仇'});}else{p.bodyState='impaired';if(p.mind)p.mind.activity='rest';else p.action='rest';if(c.cause!=='borrow-energy')p.location={kind:'local',sceneId:c.sceneId,x:43,y:24};p.wound=Math.max(p.wound||0,Math.min(35,c.injuryApplied));if(outcome==='rescued')social(s,c,'rescue');}const personal=s.stockpilesById[`stockpile:${c.personId.replace('person:','')}`];if(personal&&p.location?.kind==='local')personal.position={sceneId:p.location.sceneId,x:p.location.x,y:p.location.y};const chain=s.srCrises.rainChain;if(chain?.crisisId===c.id){chain.stage='aftermath';chain.status='resolved';chain.outcome=outcome;s.srCrises.cooldownUntil=s.worldTick+1200;s.srWorld.cooldownUntil=s.worldTick+1200;if(outcome!=='dead'){const stock=s.stockpilesById['stockpile:su-yelan'];stock.resources.herb=Math.max(0,stock.resources.herb-2);recordFactSR(s,'fact:rain:villager-care',{kind:'care',personId:c.personId,text:'苏叶岚用保留下来的草药继续照料溪口伤者'});}s.opportunitiesById[chain.id].status='resolved';}if(c.known&&distanceTo(s,c)<=6)publishFactSR(s,`fact:crisis:${c.id}:result`===c.deathFactId?c.deathFactId:recordFactSR(s,`fact:crisis:${c.id}:result`,{kind:'crisis-result',personId:c.personId,text:`危机结果：${({dead:'身死',rescued:'获救',self_rescued:'自行脱险',avoided:'识破陷阱并绕开',damaged:'危机终止，损傷保留'})[outcome]}`,sceneId:c.sceneId}).id);if(c.known&&distanceTo(s,c)<=6)log(s,`${p.name}危机：${outcome}`);}
function distanceTo(s,c){const p=s.master.location;return p?.kind==='local'&&p.sceneId===c.sceneId?Math.hypot(p.x-c.x,p.y-c.y):Infinity;}
export function searchCrisisSR(s,id){const c=s.crisesById[id];if(!c||distanceTo(s,c)>6)throw Error('需实际到线索范围内搜索，不可远程判定生死');c.known=true;const f=recordFactSR(s,`fact:crisis:${id}:found`,{kind:'observation',personId:c.personId,sceneId:c.sceneId,text:`已到场发现${s.personsById[c.personId].name}${c.outcome==='dead'?'遗体与遗物':c.status==='resolved'?'已脱离险境，现场留有处理痕迹':'被水势和洞口困住'}`});publishFactSR(s,f.id);c.lastObservation={atTick:s.worldTick,stage:c.stage,status:c.status,outcome:c.outcome,position:{x:c.x,y:c.y}};if(c.outcome==='dead'){publishFactSR(s,c.deathFactId);markAftermathKnowledge(s,c.deathFactId);discloseAftermathObligations(s,c.personId);}reconcileAftermathKnowledge(s);return c;}
export function treatCrisisSR(s,id){const c=s.crisesById[id];if(!c||c.status!=='active'||s.personsById[c.personId].lifeStatus==='dead')throw Error('已死亡者无法由普通治疗复活');if(distanceTo(s,c)>2.6)throw Error('先亲自走到伤者身边');if(s.srCrises.activeTreatment||s.srWorld.interaction||s.master.activityId)throw Error('掌门当前身体活动尚未结束');worldResourcePaySR(s,{herb:8,food:1});c.known=true;const treatment={id:`activity:treat:${id}`,kind:'sr-treatment',personId:MASTER,targetPersonId:c.personId,startedTick:s.worldTick,lastTick:s.worldTick,durationTicks:80,progressTicks:0,cost:{herb:8,food:1},status:'executing'};s.srCrises.activeTreatment={crisisId:id,...treatment};c.treatment=treatment;return treatment;}
export function setTrapSR(s,{sceneId=SCENE,x=47,y=34.5}={}){if(sceneId!==SCENE||!Number.isFinite(x)||!Number.isFinite(y)||x<2||x>62||y<2||y>46)throw Error('仅能在已交付山谷实际合法地面布置机关');const p=s.master.location;if(p?.kind!=='local'||p.sceneId!==sceneId||Math.hypot(p.x-x,p.y-y)>2.6)throw Error('布陷需要亲自到达范围');if(s.srCrises.activeTreatment||s.srWorld.interaction||s.master.activityId)throw Error('先结束现有活动');worldResourcePaySR(s,{wood:3,stone:3});s.srCrises.activeTreatment={id:`activity:trap:${s.worldTick}`,kind:'sr-trap',startedTick:s.worldTick,lastTick:s.worldTick,durationTicks:50,progressTicks:0,sceneId,x,y,cost:{wood:3,stone:3},targetPoint:{x,y},status:'executing'};return s.srCrises.activeTreatment;}
function tickCrisisStep(s){const r=s.srCrises;if(!r||r.lastTick>=s.worldTick)return;const delta=s.worldTick-r.lastTick;r.lastTick=s.worldTick;const chain=r.rainChain;
 if(chain?.stage==='departing'){const t=s.travelsById[chain.travelId];t.progressTicks=Math.min(t.durationTicks,t.progressTicks+delta);t.lastTick=s.worldTick;if(t.progressTicks===t.durationTicks){t.status='arrived';const p=s.personsById[HERBALIST];p.location={kind:'local',sceneId:SCENE,x:47,y:34.5};s.stockpilesById['stockpile:su-yelan'].position={sceneId:SCENE,x:47,y:34.5};p.mind.activity='sr-crisis';const trap=Object.values(r.traps).find(t=>t.sceneId===SCENE&&Math.hypot(t.x-47,t.y-34.5)<3&&t.status==='armed');const c=startCrisisSR(s,{id:'crisis:rain:su-yelan',personId:HERBALIST,selfRescue:p.rescueEquipment.rope>0});chain.crisisId=c.id;chain.stage='danger';if(trap&&p.mind.caution<45){trap.status='triggered';trap.targetPersonId=HERBALIST;c.cause='trapped-water-and-mechanism';c.durationTicks=780;c.injuryScale=1.1;recordFactSR(s,`fact:trap:${trap.id}:triggered`,{kind:'trap-triggered',actorId:MASTER,personId:HERBALIST,sceneId:SCENE,text:'亲设机关在实际药师到场时触发，加剧伤势；现场材料与刻痕保留'});}if(trap&&p.mind.caution>=45){trap.status='discovered';trap.discoveredBy=HERBALIST;recordFactSR(s,`fact:trap:${trap.id}:discovered`,{kind:'trap-discovered',actorId:MASTER,personId:HERBALIST,sceneId:SCENE,text:'苏叶岚察觉新刻机关，留下痕迹后绕行'});c.escapeStartedTick=s.worldTick;c.escapeOutcome='avoided';}}}
 for(const c of Object.values(s.crisesById)){if(c.status!=='active'||c.lastTick>=s.worldTick)continue;const elapsed=s.worldTick-c.lastTick;c.progressTicks=Math.min(c.durationTicks,c.progressTicks+elapsed);c.lastTick=s.worldTick;
 if(!c.messageDelivered&&s.worldTick>=c.messageDueTick){c.messageDelivered=true;const fact=recordFactSR(s,`fact:crisis:${c.id}:signal`,{kind:'delayed-message',personId:c.personId,sceneId:c.sceneId,observedTick:c.startedTick,text:`${s.personsById[c.personId].name}的旧口信：云岫山谷侧洞水势上涨，求援；消息已迟延${s.worldTick-c.startedTick}步。`});recordClaimSR(s,{id:`claim:crisis:${c.id}`,topic:'crisis',speakerId:c.personId,sourceId:fact.id,observedTick:c.startedTick,text:fact.text,evidenceFactIds:[fact.id],truthType:'outdated'});s.srWorld.knownLocations[c.personId]={sceneId:c.sceneId,observedTick:c.startedTick,sourceId:fact.id};}
 const next=c.progressTicks<100?'forming':c.progressTicks<300?'exposed':c.progressTicks<550?'engaged':c.progressTicks<750?'escalating':'critical';if(next!==c.stage){c.stage=next;c.stageStartedTick=s.worldTick;c.stageProgressTicks=0;}else c.stageProgressTicks+=elapsed;c.stageDurationTicks=next==='critical'?150:next==='forming'?100:next==='exposed'?200:next==='engaged'?250:200;
 const injury=Math.min(90,Math.floor(c.progressTicks/10))*(c.injuryScale??1);if(injury>c.injuryApplied){s.personsById[c.personId].wound=Math.min(100,(s.personsById[c.personId].wound||0)+injury-c.injuryApplied);c.injuryApplied=injury;}if(c.selfRescue&&c.progressTicks>=320&&!c.escapeStartedTick){const p=s.personsById[c.personId];if(p.rescueEquipment?.rope>0&&p.energy>=15){p.rescueEquipment.rope--;p.energy-=15;c.escapeStartedTick=s.worldTick;c.escapeOutcome='self_rescued';}}
 if(c.escapeStartedTick&&s.worldTick-c.escapeStartedTick>=60){end(s,c,c.escapeOutcome||'self_rescued');continue;}const treatment=r.activeTreatment;if(treatment?.crisisId===c.id&&treatment.kind==='sr-treatment'&&distanceTo(s,c)<=2.6&&treatment.progressTicks+(s.worldTick-treatment.lastTick)>=treatment.durationTicks){treatment.progressTicks=treatment.durationTicks;treatment.lastTick=s.worldTick;treatment.status='completed';r.activeTreatment=null;end(s,c,'rescued');continue;}if(c.progressTicks>=c.durationTicks)end(s,c,c.deathThreshold==='wound100'&&(s.personsById[c.personId].wound||0)<100?'damaged':'dead');}
 const a=r.activeTreatment;if(a){if(a.sceneId&&s.master.location?.sceneId!==a.sceneId||a.targetPoint&&Math.hypot(s.master.location.x-a.targetPoint.x,s.master.location.y-a.targetPoint.y)>2.6){a.status='interrupted';a.reason='离开实际施作位置';r.activeTreatment=null;return;}a.progressTicks=Math.min(a.durationTicks,a.progressTicks+delta);a.lastTick=s.worldTick;const c=a.crisisId&&s.crisesById[a.crisisId];if(c?.status==='active'&&distanceTo(s,c)>2.6){a.status='interrupted';r.activeTreatment=null;return;}if(a.progressTicks===a.durationTicks){if(a.kind==='sr-rope'){s.personsById[HERBALIST].rescueEquipment.rope++;recordFactSR(s,`fact:rope:${a.startedTick}`,{kind:'rescue-preparation',actorId:MASTER,personId:HERBALIST,text:'掌门实际交付编绳与行粮，苏叶岚保留是否出行及自救判断'});}else if(a.kind==='sr-trap'){const id=`trap:sr:${a.startedTick}`;r.traps[id]={id,sceneId:a.sceneId,x:a.x,y:a.y,status:'armed',actorId:MASTER,materialCost:a.cost,placedTick:s.worldTick};recordFactSR(s,`fact:${id}`,{kind:'trap',actorId:MASTER,sceneId:a.sceneId,text:'掌门亲自刻下机关，材料与痕迹留存'});}else if(c?.status==='active')end(s,c,'rescued');a.status='completed';r.activeTreatment=null;}}
 if(chain?.status==='resolved'&&s.worldTick>=r.cooldownUntil&&s.srWorld.routes['route:bridge'].condition==='blocked'){setRouteConditionSR(s,'route:bridge','damaged');recordFactSR(s,'fact:rain:recovery',{kind:'recovery',text:'雨退后旧路可慢行，桥梁仍待修复；药田和商路恢复期结束'});}}
export function tickSRCrises(s){const r=s.srCrises;if(!r||r.lastTick>=s.worldTick)return;const target=s.worldTick;try{while(r.lastTick<target){s.worldTick=r.lastTick+1;tickCrisisStep(s);}}finally{s.worldTick=target;}}
export function viewSRCrises(s){if(!s.srCrises)return null;const claims=Object.values(s.claimsById).filter(c=>c.recipients.includes(MASTER));const known=Object.values(s.crisesById).filter(c=>c.known||claims.some(m=>m.evidenceFactIds.includes(`fact:crisis:${c.id}:signal`))).map(c=>{const nearby=distanceTo(s,c)<=6,observed=nearby&&c.known,previous=c.lastObservation,learnedResult=claims.some(m=>m.evidenceFactIds.includes(`fact:crisis:${c.id}:result`)||c.deathFactId&&m.evidenceFactIds.includes(c.deathFactId));return {id:c.id,title:`${s.personsById[c.personId].name}的危机`,personId:c.personId,locationHint:'云岫山谷 · 听雨侧洞一带',stageHint:observed?c.stage:learnedResult?'终局已由现场或可靠消息核实':previous?`上次现场观察（${previous.atTick}步）：${previous.stage}`:'旧口信称水势上涨，需到场确认',status:observed||learnedResult?c.status:previous?.status||'unconfirmed',outcome:observed||learnedResult?c.outcome:previous?.outcome||null,remainingEstimate:observed&&c.status==='active'?Math.max(0,c.durationTicks-c.progressTicks):null,observedTick:observed?s.worldTick:previous?.atTick??null,approachPoint:c.known?{x:c.x,y:c.y}:null,actions:[{action:'search',label:'到场搜索',disabled:!nearby},{action:'treat',label:'草药急救（8草药、1口粮、80步）',disabled:!observed||distanceTo(s,c)>2.6||c.status!=='active'}]};});const chain=s.srCrises.rainChain,c=chain?.crisisId&&s.crisesById[chain.crisisId],visibleResult=c&&(distanceTo(s,c)<=6&&c.known||claims.some(m=>m.evidenceFactIds.includes(c.deathFactId)||m.evidenceFactIds.includes(`fact:crisis:${c.id}:result`)));const herbalist=s.personsById[HERBALIST],m=s.master.location,visible=herbalist?.lifeStatus!=='dead'&&m?.kind==='local'&&herbalist?.location?.kind==='local'&&m.sceneId===herbalist.location.sceneId;const preparation=visible?{personId:HERBALIST,name:herbalist.name,sceneId:herbalist.location.sceneId,approachPoint:{x:herbalist.location.x,y:herbalist.location.y},canSupplyRope:!chain&&Math.hypot(m.x-herbalist.location.x,m.y-herbalist.location.y)<=2.6&&!s.srCrises.activeTreatment,label:'备绳与行粮（2木、1口粮，30步）'}:null;const trapPlan=m?.kind==='local'&&m.sceneId===SCENE?{sceneId:SCENE,x:m.x,y:m.y,label:'在实际脚边布设机关（3木、3石，50步）；需承担伤害与可被察觉的痕迹'}:null;return {aftermath:viewAftermath(s),known,preparation,trapPlan,unknownOverdue:[],rainChain:chain?{stage:visibleResult?'aftermath':known.length?'awaiting-confirmation':'departing',activatedTick:chain.activatedTick}:null,treatment:s.srCrises.activeTreatment?{kind:s.srCrises.activeTreatment.kind,progressTicks:s.srCrises.activeTreatment.progressTicks,durationTicks:s.srCrises.activeTreatment.durationTicks}:null,cooldownUntil:visibleResult?s.srCrises.cooldownUntil:null};}
export function srCrisisCommand(s,payload={}){switch(payload.action){case'aftermath':return aftermathAction(s,payload);case'treat':return treatCrisisSR(s,payload.crisisId);case'search':return searchCrisisSR(s,payload.crisisId);case'trap':return setTrapSR(s,payload);case'supplyRope':{const p=s.personsById[HERBALIST],m=s.master.location;if(s.srCrises.rainChain||p.location.kind!=='local'||m.kind!=='local'||m.sceneId!==p.location.sceneId||Math.hypot(m.x-p.location.x,m.y-p.location.y)>2.6)throw Error('出发前亲自到药师身边提供准备');if(s.srCrises.activeTreatment||s.srWorld.interaction||s.master.activityId)throw Error('先结束现有身体活动');worldResourcePaySR(s,{wood:2,food:1});s.srCrises.activeTreatment={id:`activity:rope:${s.worldTick}`,kind:'sr-rope',sceneId:p.location.sceneId,targetPoint:{x:p.location.x,y:p.location.y},startedTick:s.worldTick,lastTick:s.worldTick,durationTicks:30,progressTicks:0,status:'executing'};return s.srCrises.activeTreatment;}case'cancel':if(!s.srCrises.activeTreatment)throw Error('没有治疗活动');s.srCrises.activeTreatment.status='interrupted';s.srCrises.activeTreatment=null;return true;default:throw Error('未知危机行动');}}
export function validateSRCrises(s){if(!s.srCrises)return true;const fail=m=>{throw Error('SR危机存档异常：'+m);};for(const[id,c]of Object.entries(s.crisesById)){if(!id.startsWith('crisis:rain:')&&!id.startsWith('crisis:sr:')&&!id.startsWith('crisis:mother:'))continue;if(c.id!==id||!s.personsById[c.personId]||!Number.isSafeInteger(c.durationTicks)||c.durationTicks<1||!Number.isSafeInteger(c.progressTicks)||c.progressTicks<0||c.progressTicks>c.durationTicks||!['active','resolved'].includes(c.status)||c.startedTick>s.worldTick)fail('危机预算');if(c.outcome==='dead'&&(s.personsById[c.personId].lifeStatus!=='dead'||!s.factsById[c.deathFactId]))fail('死亡事实');if(c.treatment&&(!Number.isSafeInteger(c.treatment.durationTicks)||c.treatment.durationTicks<1))fail('救治必须耗正世界步');}for(const[id,d]of Object.entries(s.deathRecordsByPersonId)){if(!s.personsById[id]||s.personsById[id].lifeStatus!=='dead'||!s.factsById[d.factId]||s.homeMemberIds.includes(id))fail('永久死亡引用');}return true;}

export function createMotherCrisisSR(s,extraction){return startCrisisSR(s,{id:`crisis:mother:${extraction.id}`,personId:extraction.targetPersonId,sceneId:s.personsById[extraction.targetPersonId].location?.sceneId||'scene:quarry',x:s.personsById[extraction.targetPersonId].location?.x||35,y:s.personsById[extraction.targetPersonId].location?.y||19,cause:'borrow-energy',durationTicks:260,injuryScale:0,deathThreshold:'wound100',messageDelayTicks:30});}
export function resolveMotherCrisisSR(s,extraction){const c=s.crisesById[`crisis:mother:${extraction.id}`];if(c?.status==='active')end(s,c,'damaged');return c;}
export function motherCriticalOutcomeSR(s,p,extraction){const c=s.crisesById[`crisis:mother:${extraction.id}`];if(c?.status==='active')end(s,c,(p.wound||0)>=100?'dead':'damaged');return c;}
